class Solution:
    def modifyString(self, s: str) -> str:
        s = list(s)
        for i in range(len(s)):
            if s[i] == '?':
                ahead = ' ' if i == 0 else s[i - 1]
                behind = ' ' if i == len(s) - 1 else s[i + 1]
                for c in string.ascii_lowercase:
                    if c != ahead and c != behind:
                        s[i] = c
                        break
        return "".join(s)

class Solution {
    public String modifyString(String s) {
        char[] chars = s.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] == '?') {
                // 前面的字符
                char ahead = i == 0 ? ' ' : chars[i - 1];
                // 后面的字符
                char behind = i == chars.length - 1 ? ' ' : chars[i + 1];
                char temp = 'a';
                while (temp == ahead || temp == behind) {
                    temp++;
                }
                chars[i] = temp;
            }
        }
        return new String(chars);
    }
}

func modifyString(s string) string {
	data := []byte(" " + s + " ")
	for i, c := range data {
		if c == byte('?') {
			ahead, behind := data[i-1], data[i+1]
			for t := byte('a'); t <= byte('z'); t++ {
				if t != ahead && t != behind {
					data[i] = t
				}
			}
		}
	}
	return string(data[1 : len(data)-1])
}

class Solution(object):
    def modifyString(self, s):
        """
        :type s: str
        :rtype: str
        """
        c = set("abcdefghijklmnopqrstuvwxyz")
        new_s = list(s)
        for i in range(len(new_s)):
            if new_s[i] != "?":
                continue
            cur_set = []
            if i != 0:
                cur_set.append(new_s[i - 1])
            if i != len(new_s) - 1:
                cur_set.append(new_s[i + 1])
            new_s[i] = list(c - set(cur_set))[0]
        return "".join(new_s)
